export const OFFICIAL_BLOGGER_LOGO_URL =
  "https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjQCg77zUT43bZxFpwtQv8VnbT6iNll_bgvVVG9xRlvSVzZ6IL25hl4cjtp0ZZZh3YwIlykgT0jn5SYPBIxjMSFzzmc1YwbUBmLCY8_9hVMFX6_UhlSAe_Zmmy52tkhPuFCIRUmEWccW6r493-6dX9k6lyHbXYvWieQ21xAzo59aryPb1mcvb6juDpp0Zo/s1600/logo.jpg";

export const OFFICIAL_LOGO_BASE64 =
  "data:image/jpeg;base64,";

export const LOCAL_LOGO_URL = "/logo.jpg";

/**
 * Retorna a imagem base64 ou URL segura da logo, evitando bloqueios de CORS do Blogger
 */
export function getSafeLogoSrc(url?: string): string {
  if (!url || url.trim() === "" || url === OFFICIAL_BLOGGER_LOGO_URL || url.includes("blogger.googleusercontent.com")) {
    return OFFICIAL_LOGO_BASE64;
  }
  return url;
}
